const TabymojiAnimation* Tabymoji_GetById(const char* id) {
    if (!id || id[0] == '\0') return &k_tabymoji_animations[0]; // default idle
    for (size_t i = 0; i < sizeof(k_tabymoji_animations) / sizeof(k_tabymoji_animations[0]); i++) {
        if (strcmp(id, k_tabymoji_animations[i].id) == 0) {
            return &k_tabymoji_animations[i];
        }
    }
    return nullptr;
}

const TabymojiAnimation* Tabymoji_GetByEmotion(const char* emotion) {
    if (!emotion || emotion[0] == '\0') return Tabymoji_GetById("idle_01_loop");
    if (strcmp(emotion, "happy") == 0 || strcmp(emotion, "joyful") == 0 || strcmp(emotion, "pleased") == 0 || strcmp(emotion, "proud") == 0) {
        return Tabymoji_GetById("thumbs_up");
    }
    if (strcmp(emotion, "sad") == 0 || strcmp(emotion, "crying") == 0 || strcmp(emotion, "grief") == 0) {
        return Tabymoji_GetById("disappointed");
    }
    if (strcmp(emotion, "surprise") == 0 || strcmp(emotion, "shocked") == 0 || strcmp(emotion, "wow") == 0) {
        return Tabymoji_GetById("wow");
    }
    if (strcmp(emotion, "sleepy") == 0 || strcmp(emotion, "sleep") == 0) {
        return Tabymoji_GetById("sleeping_loop");
    }
    if (strcmp(emotion, "angry") == 0 || strcmp(emotion, "annoyed") == 0) {
        return Tabymoji_GetById("hello_disappointed");
    }
    if (strcmp(emotion, "thinking") == 0 || strcmp(emotion, "loading") == 0) {
        return Tabymoji_GetById("circle");
    }
    if (strcmp(emotion, "calm") == 0 || strcmp(emotion, "relaxed") == 0) {
        return Tabymoji_GetById("calm_idle_01_to_f137");
    }
    if (strcmp(emotion, "neutral") == 0 || strcmp(emotion, "robot_2") == 0) {
        return Tabymoji_GetById("idle_01_loop");
    }
    // Try matching ID directly
    const TabymojiAnimation* anim = Tabymoji_GetById(emotion);
    if (anim) return anim;
    return Tabymoji_GetById("idle_01_loop");
}

const TabymojiAnimation* Tabymoji_GetByStatus(const char* status) {
    if (!status || status[0] == '\0') return Tabymoji_GetById("idle_01_loop");
    if (strstr(status, "聆听") || strstr(status, "Listen") || strstr(status, "listen")) {
        return Tabymoji_GetById("listening_in");
    }
    if (strstr(status, "说话") || strstr(status, "Speak") || strstr(status, "speak")) {
        return Tabymoji_GetById("calm_idle_01_to_f137");
    }
    if (strstr(status, "连接") || strstr(status, "Connect") || strstr(status, "connect") || strstr(status, "Wait") || strstr(status, "wait")) {
        return Tabymoji_GetById("circle");
    }
    if (strstr(status, "待命") || strstr(status, "Standby") || strstr(status, "standby") || strstr(status, "Idle") || strstr(status, "idle")) {
        return Tabymoji_GetById("idle_01_loop");
    }
    return Tabymoji_GetById("idle_01_loop");
}

size_t Tabymoji_GetAnimationCount(void) {
    return sizeof(k_tabymoji_animations) / sizeof(k_tabymoji_animations[0]);
}

const TabymojiAnimation* Tabymoji_GetByIndex(size_t index) {
    if (index < sizeof(k_tabymoji_animations) / sizeof(k_tabymoji_animations[0])) {
        return &k_tabymoji_animations[index];
    }
    return nullptr;
}
